import React, { useEffect, useState } from "react";
import { getDocs, collection, deleteDoc, doc } from "firebase/firestore";
import { auth, db } from "../firebase-config";
import CommentSection from "./CommentSection";

function Home({ isAuth }) {
  const [postLists, setPostList] = useState([]);
  const [selectedTopic, setSelectedTopic] = useState("Все");
  const [availableTopics, setAvailableTopics] = useState(["Все"]);
  const postsCollectionRef = collection(db, "posts");

  // Удаление поста
  const deletePost = async (id) => {
    const postDoc = doc(db, "posts", id);
    await deleteDoc(postDoc);
    refreshPosts();
  };

  // Обновление списка постов
  const refreshPosts = async () => {
    const data = await getDocs(postsCollectionRef);
    const posts = data.docs.map((doc) => ({ ...doc.data(), id: doc.id }));

    // Обновление доступных тем
    const topics = [...new Set(posts.map(post => post.topic || "Общее"))];
    setAvailableTopics(["Все", ...topics]);

    setPostList(posts);
  };

  useEffect(() => {
    refreshPosts();
  }, [postsCollectionRef]);

  // Фильтрация постов по теме
  const filteredPosts = selectedTopic === "Все" 
    ? postLists 
    : postLists.filter(post => post.topic === selectedTopic);

  return (
    <div className="homePage">
      <div className="filter-container">
        <h2>Фильтр задач</h2>
        <div className="filter-controls">
          <label>Тема:</label>
          <select
            value={selectedTopic}
            onChange={(e) => setSelectedTopic(e.target.value)}
          >
            {availableTopics.map((topic, index) => (
              <option key={index} value={topic}>{topic}</option>
            ))}
          </select>
        </div>
      </div>

      {filteredPosts.map((post) => {
        return (
          <div className="post" key={post.id}>
            <div className="postHeader">
              <div className="title">
                <h1>{post.title}</h1>
                <span className="topic-badge">{post.topic || "Общее"}</span>
              </div>
              <div className="deletePost">
                {isAuth && post.author.id === auth.currentUser.uid && (
                  <button
                    onClick={() => {
                      deletePost(post.id);
                    }}
                  >
                    &#128465;
                  </button>
                )}
              </div>
            </div>
            <div className="postTextContainer"> 
              {post.postText.split('\n').map((line, i) => (
                <p key={i}>{line}</p>
              ))}
            </div>
            <div className="postFooter">
              <h3>@{post.author.name}</h3>
            </div>

            {/* Секция комментариев */}
            <CommentSection 
              postId={post.id} 
              isAuth={isAuth} 
            />
          </div>
        );
      })}
    </div>
  );
}

export default Home;
